const state=load(); let master={products:[],recipes:[]}; let current=location.hash.slice(1)||'dashboard'; if(!MODULES.some(m=>m[0]===current))current='dashboard';
function load(){let s={};try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))s=parsed}}catch(e){s={}}; if(!Object.keys(s).length){for(const k of LEGACY_KEYS){try{const raw=localStorage.getItem(k);if(raw){const parsed=JSON.parse(raw);if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed)){s=parsed;break}}}catch(e){}}} for(const k of ['products','ingredients','categories','suppliers','purchases','purchasePriceHistory','shopping','inventory','movements','waste','sales','promotions','events','production','labels','notes','records','dreRecords','budgets','recipes','preps','physicalCounts','barcodeLog','barRecipes','barPreps','checklistTasks','managerLogs','incidents','maintenance','equipment','users','audit','employees','employeeDocs','employeeConsumptions','labor','resources','partners','capitalMoves','companyAssets','companyNotes','companyIncidents','companyDocuments','companyResponsibilities','financialDocuments','loans','loanPayments','digitalAssets','permits','refrigerationMoves','documents'])s[k]=Array.isArray(s[k])?s[k]:[];if(!s.users.length)s.users=[{id:'USR-ADMIN',name:'Administrador LRX',role:'Admin',active:true,createdAt:new Date().toISOString()}];s.currentUserId=s.currentUserId||'USR-ADMIN';s.settings={labelFormats:[{name:'4 × 3 in',w:4,h:3},{name:'3 × 2 in',w:3,h:2}],shelfLifeDefault:3,targetFoodCost:30,targetContributionMargin:70,distributionReservePct:30,credentialRevealLog:true,priceIncreaseAlertPct:10,priceIncreaseAlertEnabled:true,inventoryLocations:['Almacén','Cocina','Bar','Nevera','Congelador','Producción'],channels:[{name:'Salón',type:'Directo',commission:0,cardFeePct:0,fixedFee:0,active:true},{name:'Uber Eats',type:'Delivery',commission:49,cardFeePct:0,fixedFee:0,active:true},{name:'DoorDash',type:'Delivery',commission:30,cardFeePct:0,fixedFee:0,active:true},{name:'Pickup',type:'Directo',commission:0,cardFeePct:0,fixedFee:0,active:true}],...(s.settings||{})};return s}
state.masterOverrides=state.masterOverrides&&typeof state.masterOverrides==='object'?state.masterOverrides:{};state.masterHidden=state.masterHidden&&typeof state.masterHidden==='object'?state.masterHidden:{};for(const k of ['products','recipes','preps'])state.masterHidden[k]=Array.isArray(state.masterHidden[k])?state.masterHidden[k]:[];
function effectiveMaster(type){
 const isPrep=type==='preps';
 const isSupplier=type==='suppliers';
 const base=isSupplier?((state.suppliers&&state.suppliers.length)?state.suppliers:(master.suppliers||[]).map((x,i)=>typeof x==='string'?{id:'SUPP-'+String(i+1).padStart(3,'0'),name:x}:x)):(type==='products'?(master.products||[]):(master.recipes||[]).filter(r=>isPrep?String(r.type||'').toLowerCase()==='pre':String(r.type||'').toLowerCase()!=='pre'));
 const hidden=new Set(state.masterHidden[isPrep?'recipes':type]||[]);
 return base.filter(x=>!hidden.has(String(x.id))).map(x=>({...x,...(state.masterOverrides[isPrep?'recipes':type]?.[x.id]||{})}));
}
function findRecipeAny(type,id){const key=type==='final'?'recipes':'preps';return (state[key]||[]).find(x=>String(x.id)===String(id)) || effectiveMaster(type==='final'?'recipes':'preps').find(x=>String(x.id)===String(id));}
function cloneMasterProduct(id){const base=(master.products||[]).find(x=>String(x.id)===String(id));if(!base)return null;const clone={...base,id:'USR-P-'+Date.now(),masterId:base.id,source:'EDITADO DESDE SUP',createdAt:now()};state.products.push(clone);state.masterHidden.products.push(base.id);save();return clone;}
function cloneMasterRecipe(type,id){const key=type==='final'?'recipes':'preps';const base=(master.recipes||[]).find(x=>String(x.id)===String(id));if(!base)return null;const clone=JSON.parse(JSON.stringify({...base,id:'USR-'+(type==='final'?'R-':'P-')+Date.now(),masterId:base.id,source:'EDITADO DESDE MAESTRO',createdAt:now()}));state[key].push(clone);state.masterHidden.recipes.push(base.id);save();return clone;}
let lastAction='system';
const ROLE_SECURE={Socio:{view:true,create:true,edit:true,delete:true,print:true,pdf:true,excel:true,approve:true,discount:false,price:true,cost:true,finance:true},'Accionista/Inversionista':{view:true,create:true,edit:true,delete:true,print:true,pdf:true,excel:true,approve:true,discount:false,price:true,cost:true,finance:true},Finanzas:{view:true,create:true,edit:true,delete:true,print:true,pdf:true,excel:true,approve:true,discount:false,price:true,cost:true,finance:true},Administración:{view:true,create:true,edit:true,delete:true,print:true,pdf:true,excel:true,approve:true,discount:true,price:true,cost:true,finance:true},'Gerente General':{view:true,create:true,edit:true,delete:true,print:true,pdf:true,excel:true,approve:true,discount:true,price:true,cost:true,finance:true}};
const ROLES={Admin:{view:true,create:true,edit:true,delete:true,print:true,pdf:true,excel:true,approve:true,discount:true,price:true,cost:true,finance:true},Manager:{view:true,create:true,edit:true,delete:false,print:true,pdf:true,excel:true,approve:true,discount:true,price:true,cost:true,finance:true},Purchasing:{view:true,create:true,edit:true,delete:false,print:true,pdf:true,excel:true,approve:true,discount:false,price:false,cost:true,finance:false},Kitchen:{view:true,create:true,edit:true,delete:false,print:true,pdf:true,excel:false,approve:false,discount:false,price:false,cost:true,finance:false},Bar:{view:true,create:true,edit:true,delete:false,print:true,pdf:true,excel:false,approve:false,discount:false,price:false,cost:true,finance:false},'POS/Cashier':{view:true,create:true,edit:true,delete:false,print:true,pdf:true,excel:false,approve:false,discount:true,price:false,cost:false,finance:false},Inventory:{view:true,create:true,edit:true,delete:false,print:true,pdf:true,excel:true,approve:true,discount:false,price:false,cost:true,finance:false}};
function currentUser(){return state.users.find(u=>u.id===state.currentUserId)||state.users[0]||{id:'USR-ADMIN',name:'Administrador LRX',role:'Admin',active:true}}
function lrxNotifications(){const out=[];const pct=Number(state.settings?.priceIncreaseAlertPct||10);if(state.settings?.priceIncreaseAlertEnabled!==false){(state.purchasePriceHistory||[]).slice().reverse().forEach(h=>{if(Number(h.increasePct||0)>=pct)out.push({type:'PRECIO',title:'Aumento de costo',detail:`${h.product||'Producto'} · +${Number(h.increasePct||0).toFixed(1)}%`,date:h.date||h.createdAt})})}(state.permits||[]).forEach(r=>{if(r.expiryDate){const days=Math.ceil((new Date(r.expiryDate+'T23:59:59').getTime()-Date.now())/86400000);if(days<=30)out.push({type:'VENCIMIENTO',title:days<0?'Documento vencido':'Vencimiento próximo',detail:`${r.name||'Documento'} · ${days<0?'vencido':days+' días'}`,date:r.expiryDate})}});(state.inventory||[]).forEach(i=>{const min=Number(i.minQty||0);if(min>0&&Number(i.qty||0)<=min)out.push({type:'INVENTARIO',title:'Stock bajo',detail:`${i.product||'Producto'} · ${Number(i.qty||0)} ${i.unit||''}`,date:now()})});return out.slice(0,40)}
function notificationModal(){const rows=lrxNotifications();modal(`<h3>Notificaciones LRX</h3><p class="muted">Alertas operativas pendientes.</p><div class="card">${rows.map(r=>`<div class="check-row" style="display:block;padding:10px 0;border-bottom:1px solid var(--line)"><b>${esc(r.title)}</b><br><small>${esc(r.detail)} · ${esc(r.date||'')}</small></div>`).join('')||'<div class="empty">No hay alertas pendientes.</div>'}</div><div class="actions"><button class="btn primary" data-action="close">Cerrar</button></div>`)}
function profileModal(){const u=currentUser();modal(`<h3>Perfil activo</h3><div class="card"><p><b>${esc(u.name||'Administrador LRX')}</b></p><p class="muted">Rol: ${esc(u.role||'Admin')}</p><p class="muted">ID: ${esc(u.id||'')}</p></div><div class="actions"><button class="btn" data-action="close">Cerrar</button><button class="btn primary" data-action="go-users">Usuarios y permisos</button></div>`)}

const SECURE_ROLES=['Admin','Socio','Accionista/Inversionista','Finanzas','Administración','Gerente General'];
function secureAccess(){return SECURE_ROLES.includes(currentUser().role)}
function requireSecure(){if(!secureAccess()){toast('Módulo restringido: solo socios/inversionistas y personal administrativo-financiero autorizado');return false}return true}
function exportValue(v){if(v===null||v===undefined)return '';if(v instanceof Date)return v.toISOString();if(typeof v==='object'){try{return JSON.stringify(v)}catch(e){return String(v)}}return String(v)}
function csvEscape(v){return JSON.stringify(exportValue(v))}
function exportRows(rows,name){if(!Array.isArray(rows)||!rows.length)return toast('No hay datos para exportar');const safe=rows.filter(r=>r&&typeof r==='object');if(!safe.length)return toast('No hay datos válidos para exportar');const headers=[...new Set(safe.flatMap(r=>Object.keys(r)))];const csv='\ufeff'+[headers.map(csvEscape).join(','),...safe.map(r=>headers.map(h=>csvEscape(r[h])).join(','))].join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${name}_${new Date().toISOString().slice(0,10)}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportRowsCSV(rows,name){return exportRows(rows,name)}
function exportExcel(rows,name){if(!rows.length)return toast('No hay datos para exportar');const headers=[...new Set(rows.flatMap(r=>Object.keys(r)))];const escX=v=>esc(exportValue(v));const html=`<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="UTF-8"><!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>LRX</x:Name><x:WorksheetOptions><x:DisplayGridlines/></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]--></head><body><table border="1"><thead><tr>${headers.map(h=>`<th>${escX(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${headers.map(h=>`<td>${escX(r[h])}</td>`).join('')}</tr>`).join('')}</tbody></table></body></html>`;const blob=new Blob([html],{type:'application/vnd.ms-excel;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${name}_${new Date().toISOString().slice(0,10)}.xls`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function printHtml(title,body){
 const host=document.body, appShell=document.getElementById('app')||document.getElementById('root')||document.body;
 const previous=document.getElementById('lrxPrintOverlay'); if(previous) previous.remove();
 const overlay=document.createElement('div');overlay.id='lrxPrintOverlay';overlay.innerHTML=`<div class="lrx-print-page"><h1>LA REYNA MEXICAN FOOD XPRESS</h1><h2>${esc(title)}</h2>${body}<p class="small">Generado por Sistema de Gestión de Restaurante - LRX · ${fmt(now(),true)}</p></div>`;
 host.appendChild(overlay);
 const style=document.createElement('style');style.id='lrxPrintStyle';style.textContent=`#lrxPrintOverlay{position:fixed;inset:0;background:#fff;z-index:2147483647;overflow:auto;padding:28px;color:#172033;font-family:Arial,sans-serif}#lrxPrintOverlay h1{color:#244b93;border-bottom:3px solid #c92d6f;padding-bottom:10px}#lrxPrintOverlay table{width:100%;border-collapse:collapse}#lrxPrintOverlay th,#lrxPrintOverlay td{padding:8px;border:1px solid #ddd;text-align:left}#lrxPrintOverlay th{background:#f4f6fa}.lrx-print-page{max-width:1100px;margin:0 auto}.lrx-print-page .small{color:#667085;font-size:12px;margin-top:18px}@media print{body>*:not(#lrxPrintOverlay){display:none!important}#lrxPrintOverlay{position:static!important;overflow:visible!important;padding:0!important}#lrxPrintOverlay .lrx-print-page{max-width:none!important}}`;host.appendChild(style);
 let restored=false;const restore=()=>{if(restored)return;restored=true;overlay.remove();style.remove();window.removeEventListener('afterprint',restore);};window.addEventListener('afterprint',restore);
 setTimeout(()=>{window.print();setTimeout(restore,1200)},80);
}
function secureModule(title,subtitle,collection,fields,opts={}){if(!requireSecure())return head(title,subtitle)+`<div class=card><b>Acceso restringido.</b></div>`;const rows=state[collection]||[];const q=String(state[`_${collection}Q`]||'').toLowerCase();const filtered=rows.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q));const cols=fields.map(f=>f.key);const actions=`<button class="btn primary" data-action="secure-new" data-key="${collection}">＋ Nuevo</button> <button class="btn" data-action="secure-export" data-key="${collection}">Excel / CSV</button> <button class="btn" data-action="secure-print" data-key="${collection}">Imprimir / PDF</button>`;return head(title,subtitle,actions)+`<div class=card><div class=toolbar><input class="input search" id="secureSearch" data-key="${esc(collection)}" value="${esc(state[`_${collection}Q`]||'')}" placeholder="Buscar en ${esc(title)}..."></div><div class=tablewrap><table><thead><tr>${fields.map(f=>`<th>${esc(f.label)}</th>`).join('')}<th>Acciones</th></tr></thead><tbody>${filtered.slice().reverse().map(r=>`<tr>${cols.map(k=>`<td>${esc(r[k]??'—')}</td>`).join('')}<td><button class="btn" data-action="secure-edit" data-key="${collection}" data-id="${esc(r.id)}">Editar</button> <button class="btn danger" data-action="secure-delete" data-key="${collection}" data-id="${esc(r.id)}">Eliminar</button></td></tr>`).join('')||`<tr><td class=empty colspan=${fields.length+1}>No hay registros.</td></tr>`}</tbody></table></div></div>`}

function perms(){return ROLES[currentUser().role]||ROLE_SECURE[currentUser().role]||ROLES.Admin}
function permissionForAction(a){if(a.startsWith('export-')||a==='generic-export'||a==='inventory-export')return 'excel';if(a==='generic-print'||a==='print-label'||a==='print-event'||a==='print-checklist')return 'print';if(a.includes('delete')||a.startsWith('del-'))return 'delete';if(a.startsWith('new-')||a.startsWith('save-')||a.startsWith('add-')||a.startsWith('update-')||a.startsWith('quick-')||a.startsWith('start-')||a.startsWith('finish-')||['generic-add','edit-product','edit-note','edit-recipe','edit-bar','buy-shopping','inventory-adjust','inventory-count','save-adjust','save-physical-count','toggle-check','pin-note','switch-user','save-settings'].includes(a))return 'create';return 'view'}
function canAction(a){if(['new-user','save-user','delete-user','switch-user'].includes(a)&&currentUser().role!=='Admin'){toast('Solo Admin puede administrar usuarios');return false}const need=permissionForAction(a);if(perms()[need]!==false)return true;toast('No tienes permiso para esta acción');return false}
function audit(event,detail=''){state.audit=Array.isArray(state.audit)?state.audit:[];state.audit.unshift({id:'AUD-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),date:new Date().toISOString(),userId:currentUser().id,user:currentUser().name,role:currentUser().role,event,action:lastAction,detail});state.audit=state.audit.slice(0,1000)}
function save(){audit('PERSISTENCIA','Cambio guardado en el almacenamiento local');try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(KEY+'.backup',JSON.stringify({savedAt:new Date().toISOString(),state}))}catch(e){toast('No fue posible guardar: almacenamiento lleno o bloqueado')}}
function nextCode(prefix,collection,minimum=1){const rows=Array.isArray(state[collection])?state[collection]:[];const re=new RegExp('^'+prefix+'-(\\d+)$','i');let max=0;rows.forEach(x=>{const m=String(x?.id||'').match(re);if(m)max=Math.max(max,Number(m[1])||0)});return prefix+'-'+String(Math.max(max+1,minimum)).padStart(3,'0')}
function nextCatalogCode(){const used=[...(master.products||[]),...(state.products||[])].map(x=>String(x?.id||'')).filter(x=>/^SUP-\d+$/i.test(x));let max=0;used.forEach(x=>max=Math.max(max,Number(x.split('-')[1])||0));return 'SUP-'+String(max+1).padStart(3,'0')}
function nextSupplierCode(){const used=[...(master.suppliers||[]),...(state.suppliers||[])].map(x=>String(x?.id||'')).filter(x=>/^SUPP-\d+$/i.test(x));let max=0;used.forEach(x=>max=Math.max(max,Number(x.split('-')[1])||0));return 'SUPP-'+String(max+1).padStart(3,'0')}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))} function money(v){return Number(v||0).toLocaleString('en-US',{style:'currency',currency:'USD'})} function fmt(v,withTime=false){if(!v)return'—';return new Date(v).toLocaleString('es-US',withTime?{dateStyle:'short',timeStyle:'short'}:{dateStyle:'short'})} function now(){return new Date().toISOString()}
function toast(t){const x=document.getElementById('toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
function renderNav(){const n=document.getElementById('nav');let last='';n.innerHTML=MODULES.filter(m=>perms().view).map(m=>{const g=m[0]==='dashboard'?'':group(m[0]);let h='';if(g&&g!==last){last=g;h=`<div class="group">${g}</div>`}return h+`<button type="button" data-page="${m[0]}" class="${m[0]===current?'active':''}" aria-current="${m[0]===current?'page':'false'}"><span class="nav-icon" aria-hidden="true">${icon(m[0])}</span><span class="nav-label">${esc(m[1])}</span></button>`}).join('')}
function group(id){if(['dashboard','inteligencia','sup','dre'].includes(id))return'PRINCIPAL';if(['productos','ingredientes','categorias','proveedores','proveedores-comparacion'].includes(id))return'CATÁLOGOS';if(['compras','lista-compras','inventario','movimientos','merma'].includes(id))return'ABASTECIMIENTO';if(['recetas','preelaborados','produccion','cocina','bar'].includes(id))return'PRODUCCIÓN';if(['ventas','rentabilidad','foodcost','menu','finanzas','promociones','eventos'].includes(id))return'GESTIÓN';if(['reportes','checklists','gerente','nas'].includes(id))return'CONTROL';return'HERRAMIENTAS'}
