 `<div class="card" style="margin-top:14px"><div class="tablewrap"><table><thead><tr><th>Receta</th><th>Precio</th><th>Costo/u</th><th>Food Cost</th><th>Precio objetivo</th><th>Utilidad/u</th><th>Margen</th><th>Estado</th></tr></thead><tbody id="foodcostRows">${rows.map(r=>`<tr data-search="${esc(JSON.stringify(r).toLowerCase())}"><td><b>${esc(r.name)}</b><small class="muted">${esc(r.y)} ${esc(r.yieldUnit||'')}</small></td><td>${r.price?money(r.price):'—'}</td><td>${money(r.cu)}</td><td>${r.price&&r.d.complete?r.fc.toFixed(1)+'%':'—'}</td><td>${r.targetPrice?money(r.targetPrice):'—'}</td><td>${r.price?money(r.profit):'—'}</td><td>${r.price?r.margin.toFixed(1)+'%':'—'}</td><td><span class="status">${esc(r.status)}</span>${r.d.missing.length?`<small class="muted">Faltan: ${esc(r.d.missing.slice(0,2).join(', '))}${r.d.missing.length>2?'…':''}</small>`:''}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No hay recetas.</td></tr>'}</tbody></table></div></div>`;
