 const rows=Object.values(map).map(x=>({...x,margin:x.net?x.profit/x.net*100:0,foodCost:x.net?x.cost/x.net*100:0})),totalQty=rows.reduce((a,r)=>a+r.qty,0),avgQty=rows.length?totalQty/rows.length:0,avgMargin=rows.length?rows.reduce((a,r)=>a+r.margin,0)/rows.length:0;
