 const openInc=incidents.filter(r=>String(r.status||'ABIERTO').toUpperCase()!=='CERRADO').length, openMaint=maintenance.filter(r=>String(r.status||'PENDIENTE').toUpperCase()!=='COMPLETADO').length, pendingChecks=checklist.filter(r=>!r.done).length;
 const snapshot=[['Ventas',sales.length,money(saleNet)],['Compras',purchases.length,money(purchaseTotal)],['Inventario',inv.length,money(invValue)],['Merma',waste.length,money(wasteCost)],['Producción',prod.length,String(prod.filter(r=>String(r.status).toUpperCase()==='FINALIZADA').length)+' finalizadas'],['Eventos',events.length,money(events.reduce((a,r)=>a+Number(r.total||0),0))],['Empleados',employees.length,money(laborCost)],['Consumos internos',diets.length,money(dietCost)],['Incidentes abiertos',openInc,'pendientes'],['Mantenimiento pendiente',openMaint,'pendientes'],['Checklist pendiente',pendingChecks,'tareas']];
 const rows=[...sales.map((r,i)=>({modulo:'Ventas',id:r.id,fecha:r.date||r.createdAt,detalle:r.product,estado:r.status||'REGISTRADA',monto:saleDetails[i]?.net||0})),...purchases.map(r=>({modulo:'Compras',id:r.id,fecha:r.date||r.createdAt,detalle:r.product,estado:r.status||'REGISTRADA',monto:Number(r.total||0)})),...waste.map(r=>({modulo:'Merma',id:r.id,fecha:r.date||r.createdAt,detalle:r.product,estado:r.reason||'REGISTRADA',monto:Number(r.wasteCost||0)})),...prod.map(r=>({modulo:'Producción',id:r.id,fecha:r.date||r.createdAt,detalle:r.product||r.prepName,estado:r.status||'REGISTRADA',monto:Number(r.totalCost||0)})),...events.map(r=>({modulo:'Catering',id:r.id,fecha:r.date||r.createdAt,detalle:r.name,estado:r.status||'ESTIMADO',monto:Number(r.total||0)})),...diets.map(r=>({modulo:'Consumos internos',id:r.id,fecha:r.date||r.createdAt,detalle:r.product,estado:r.type||'CONSUMO',monto:Number(r.cost||0)})),...incidents.map(r=>({modulo:'Incidentes',id:r.id,fecha:r.date||r.createdAt,detalle:r.title,estado:r.status||'ABIERTO',monto:0})),...maintenance.map(r=>({modulo:'Mantenimiento',id:r.id,fecha:r.date||r.createdAt,detalle:r.equipment,estado:r.status||'PENDIENTE',monto:Number(r.cost||0)}))];
 return head('Reportes','Centro de reportes con datos reales de la operación.',`<div class="toolbar"><input id="reportSearch" class="input search" placeholder="Buscar módulo, producto, estado..." value="${esc(state._reportQ||'')}"><select id="reportModule" class="input"><option value="">Todos los módulos</option>${[...new Set(rows.map(r=>r.modulo))].sort().map(x=>`<option ${state._reportModule===x?'selected':''}>${esc(x)}</option>`).join('')}</select><input id="reportFrom" class="input" type="date" value="${esc(state._reportFrom||'')}"><input id="reportTo" class="input" type="date" value="${esc(state._reportTo||'')}"><button class="btn primary" data-action="export-report">Exportar Excel + CSV</button><button class="btn" data-action="report-print">Imprimir / PDF</button></div>`)+
 `<div class="grid"><div class="card kpi"><small>Ventas netas</small><strong>${money(saleNet)}</strong></div><div class="card kpi"><small>Costo de ventas</small><strong>${money(saleCost)}</strong></div><div class="card kpi"><small>Comisiones + tarjeta + cargos</small><strong>${money(fees)}</strong></div><div class="card kpi"><small>Utilidad operacional de ventas</small><strong>${money(saleProfit)}</strong></div></div>`+
 `<div class="grid" style="margin-top:14px">${snapshot.map(r=>`<div class="card"><small>${esc(r[0])}</small><h3>${esc(String(r[1]))}</h3><span class="muted">${esc(String(r[2]))}</span></div>`).join('')}</div>`+
 `<div class="card" style="margin-top:14px"><h3>Detalle consolidado</h3><div class="tablewrap"><table><thead><tr><th>Módulo</th><th>Fecha</th><th>Detalle</th><th>Estado</th><th>Monto</th></tr></thead><tbody id="reportRows">${rows.slice().reverse().slice(0,500).map(r=>`<tr data-report-row data-module="${esc(r.modulo)}" data-date="${esc(String(r.fecha||'').slice(0,10))}" data-search="${esc(JSON.stringify(r).toLowerCase())}"><td>${esc(r.modulo)}</td><td>${esc(r.fecha||'')}</td><td>${esc(r.detalle||'')}</td><td><span class="status">${esc(r.estado||'')}</span></td><td>${money(r.monto)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No hay movimientos.</td></tr>'}</tbody></table></div></div>`;
