function finance(){
 const rows=Array.isArray(state.dreRecords)?state.dreRecords:[],budgets=Array.isArray(state.budgets)?state.budgets:[],sales=(state.sales||[]).map(s=>saleDetail(s));
 const gross=sales.reduce((a,r)=>a+r.gross,0),discounts=sales.reduce((a,r)=>a+r.discountAmt,0),fees=sales.reduce((a,r)=>a+r.commission+r.card+r.fixedFee,0),net=sales.reduce((a,r)=>a+r.net,0),cogs=sales.reduce((a,r)=>a+r.cost,0);
 const manualIncome=rows.filter(r=>r.type==='income').reduce((a,r)=>a+Number(r.amount||0),0),manualExpense=rows.filter(r=>r.type==='expense').reduce((a,r)=>a+Number(r.amount||0),0);
 const fixedCats=['renta','rent','nómina','nomina','seguro','servicios','electricidad','agua','gas','internet','telefono','teléfono','mantenimiento','marketing'];
 const fixed=rows.filter(r=>r.type==='expense'&&fixedCats.includes(String(r.category||'').trim().toLowerCase())).reduce((a,r)=>a+Number(r.amount||0),0);
 const contribution=Math.max(0,net-cogs),cm=net>0?contribution/net*100:Number(state.settings.targetContributionMargin||70),be=cm>0?fixed/(cm/100):0;
 const actual=(cat,period)=>rows.filter(r=>r.type==='expense'&&String(r.category||'').trim().toLowerCase()===String(cat||'').trim().toLowerCase()&&(!period||String(r.date||r.createdAt||'').slice(0,7)===period)).reduce((a,r)=>a+Number(r.amount||0),0);
 const budgetFor=(cat,period)=>budgets.filter(b=>String(b.category||'').trim().toLowerCase()===String(cat||'').trim().toLowerCase()&&(!period||String(b.period||'')===period)).reduce((a,b)=>a+Number(b.amount||0),0);
 const currentPeriod=new Date().toISOString().slice(0,7),btot=budgets.filter(b=>String(b.period||'')===currentPeriod).reduce((a,r)=>a+Number(r.amount||0),0),rtot=rows.filter(r=>r.type==='expense'&&String(r.date||r.createdAt||'').slice(0,7)===currentPeriod).reduce((a,r)=>a+Number(r.amount||0),0),varia=btot-rtot;
 const cats=[...new Set(['Electricidad','Agua','Gas','Internet','Teléfono','Renta','Seguro','Mantenimiento','Nómina','Marketing',...budgets.map(b=>b.category).filter(Boolean),...rows.filter(r=>r.type==='expense').map(r=>r.category).filter(Boolean)])];
 return head('Finanzas','Presupuesto vs real, margen de contribución, punto de equilibrio y gastos operativos.',`<button class="btn primary" data-action="new-budget">＋ Nuevo presupuesto</button> <button class="btn" data-action="new-dre">＋ Registrar gasto/ingreso</button> <button class="btn" data-action="finance-export">Excel + CSV</button> <button class="btn" data-action="finance-print">Imprimir / PDF</button>`)+
 `<div class="grid"><div class="card kpi"><small>Ventas brutas POS</small><strong>${money(gross)}</strong></div><div class="card kpi"><small>Descuentos</small><strong>${money(discounts)}</strong></div><div class="card kpi"><small>Ventas netas</small><strong>${money(net)}</strong></div><div class="card kpi"><small>Comisiones + tarjeta</small><strong>${money(fees)}</strong></div><div class="card kpi"><small>COGS</small><strong>${money(cogs)}</strong></div><div class="card kpi"><small>Margen contribución</small><strong>${cm.toFixed(1)}%</strong></div><div class="card kpi"><small>Equilibrio estimado</small><strong>${money(be)}</strong></div></div>
 <div class="grid" style="margin-top:14px"><div class="card"><h3>Punto de equilibrio</h3><div class="formgrid"><div class="field"><label>Costos fijos</label><input id="beFixed" type="number" step=".01" value="${fixed.toFixed(2)}"></div><div class="field"><label>Margen contribución %</label><input id="beMargin" type="number" step=".1" value="${cm.toFixed(1)}"></div><div class="full"><button class="btn primary" data-action="equilibrium">Calcular</button><div id="beResult" class="resultbox">${be?`Ventas necesarias para equilibrio: <b>${money(be)}</b>`:'Indica un margen mayor que 0.'}</div></div></div></div>
 <div class="card"><h3>Presupuesto vs Real — ${esc(currentPeriod)}</h3><div class="grid"><div class="kpi"><small>Presupuesto</small><strong>${money(btot)}</strong></div><div class="kpi"><small>Real</small><strong>${money(rtot)}</strong></div><div class="kpi"><small>Variación</small><strong>${money(varia)}</strong></div></div></div></div>
 <div class="card" style="margin-top:14px"><h3>Gastos operativos</h3><div class="catalog-results">${cats.map(c=>{const b=budgetFor(c,currentPeriod),r=actual(c,currentPeriod),v=b-r,p=b?Math.abs(v)/b*100:0;return `<article class="catalog-card"><h3>${esc(c)}</h3><div class="catalog-grid"><div><small>Presupuesto</small><b>${money(b)}</b></div><div><small>Real mes actual</small><b>${money(r)}</b></div><div><small>Variación</small><b>${money(v)} ${b?`(${p.toFixed(1)}%)`:''}</b></div></div></article>`}).join('')||'<div class="card empty">Sin gastos registrados.</div>'}</div></div>
 <div class="card" style="margin-top:14px"><h3>Detalle de presupuestos</h3><div class="catalog-results">${budgets.slice().reverse().map(b=>{const r=actual(b.category,b.period),d=Number(b.amount||0)-r,p=Number(b.amount||0)?d/Number(b.amount)*100:0;return `<article class="catalog-card"><div class="catalog-title"><span class="status">${esc(b.period||'—')}</span><h3>${esc(b.category||'Sin categoría')}</h3></div><div class="catalog-grid"><div><small>Presupuesto</small><b>${money(b.amount)}</b></div><div><small>Real</small><b>${money(r)}</b></div><div><small>Variación</small><b>${money(d)} (${p.toFixed(1)}%)</b></div></div><div class="catalog-actions"><button class="btn" data-action="edit-budget" data-id="${esc(b.id)}">Editar</button><button class="btn danger" data-action="delete-budget" data-id="${esc(b.id)}">Eliminar</button></div></article>`}).join('')||'<div class="card empty">No hay presupuestos.</div>'}</div></div>`;
}
