function inventoryCard(x){const q=Number(x.qty||0),c=Number(x.unitCost||0),low=Number(x.minQty||0)>q&&Number(x.minQty||0)>0;return `<article class="catalog-card inventory-card"><div class="catalog-title"><span class="catalog-id">${esc(x.productId||x.id||'—')}</span><h3>${esc(x.product||'—')}</h3></div><div class="catalog-grid"><div><small>Existencia</small><b>${q.toLocaleString(undefined,{maximumFractionDigits:3})} ${esc(x.unit||'')}</b></div><div><small>Costo compra</small><b>${money(c)} / ${esc(x.unit||'')}</b></div><div><small>Costo utilizable</small><b>${money(Number(x.usableUnitCost??x.finalCost??c))} / ${esc(x.unit||'')}</b></div><div><small>Valor</small><b>${money(q*c)}</b></div><div><small>Mínimo</small><b>${Number(x.minQty||0)||'—'}</b></div><div><small>Proveedor</small><b>${esc(x.supplier||'—')}</b></div><div><small>Estado</small><b>${low?'BAJO MÍNIMO':'OK'}</b></div></div><div class="catalog-actions"><button class="btn" data-action="inventory-view" data-id="${esc(x.productId||x.id||'')}">Ver ficha</button><button class="btn" data-action="inventory-adjust" data-id="${esc(x.productId||x.id||'')}">Ajustar</button><button class="btn" data-action="inventory-count" data-id="${esc(x.productId||x.id||'')}">Conteo físico</button></div></article>`}
function inventoryProductDetail(id){const row=inventoryMasterRows().find(x=>String(x.productId||x.id)===String(id));if(!row)return toast('Producto no encontrado en inventario');const p=[...(master.products||[]),...(state.products||[])].find(x=>String(x.id)===String(row.productId)||String(x.name||'').trim().toLowerCase()===String(row.product||'').trim().toLowerCase())||{};const moves=(state.movements||[]).filter(x=>(row.productId&&String(x.productId||'')===String(row.productId))||String(x.product||'').trim().toLowerCase()===String(row.product||'').trim().toLowerCase()).slice().reverse().slice(0,20);const q=Number(row.qty||0),c=Number(row.unitCost||0),uc=Number(row.usableUnitCost??p.finalCost??p.usableCost??c),w=Number(p.wastePct??row.wastePct??0),y=Number(p.yieldFactor??row.yieldFactor??(1-w/100));modal(`<h3>Ficha de inventario</h3><p class="muted">${esc(row.product||'')}</p><div class="grid"><div class="card kpi"><small>Existencia física</small><strong>${q.toLocaleString(undefined,{maximumFractionDigits:3})} ${esc(row.unit||'')}</strong></div><div class="card kpi"><small>Costo de compra</small><strong>${money(c)} / ${esc(row.unit||'')}</strong></div><div class="card kpi"><small>Costo utilizable</small><strong>${money(uc)} / ${esc(row.unit||'')}</strong></div><div class="card kpi"><small>Merma / rendimiento</small><strong>${w.toFixed(2)}% / ${(y*100).toFixed(2)}%</strong></div></div><div class="card" style="margin-top:12px"><h4>Presentación y costo</h4><div class="catalog-grid"><div><small>Presentación</small><b>${esc(p.purchaseUnit||row.presentation||'—')}</b></div><div><small>Contenido</small><b>${p.packQty?esc(p.packQty)+' '+esc(p.packUnit||row.packUnit||row.unit):'—'}</b></div><div><small>Costo presentación</small><b>${p.packPrice!=null?money(p.packPrice):'—'}</b></div><div><small>Costo antes de merma</small><b>${money(Number(p.standardUnitCost??p.preMermaUnitCost??c))} / ${esc(row.unit||'')}</b></div><div><small>Costo después de merma</small><b>${money(uc)} / ${esc(row.unit||'')}</b></div><div><small>Proveedor</small><b>${esc(row.supplier||p.supplier||'—')}</b></div></div></div><div class="card" style="margin-top:12px"><h4>Últimos movimientos</h4><div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Cantidad</th><th>Costo</th><th>Referencia</th></tr></thead><tbody>${moves.map(m=>`<tr><td>${fmt(m.date,true)}</td><td>${esc(m.type||'—')}</td><td>${esc(m.qty)} ${esc(m.unit||'')}</td><td>${money(m.unitCost||0)}</td><td>${esc(m.ref||'—')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Sin movimientos registrados.</td></tr>'}</tbody></table></div></div><div class="actions"><button class="btn" data-action="close">Cerrar</button><button class="btn" data-action="inventory-adjust" data-id="${esc(row.productId||row.id)}">Ajustar existencia</button><button class="btn primary" data-action="edit-product" data-id="${esc(row.productId||row.id)}">Editar producto</button></div>`)}
function inventoryCountModal(prefill=''){const p=inventoryMasterRows().find(x=>String(x.productId||x.id)===String(prefill)||String(x.product||'').trim().toLowerCase()===String(prefill||'').trim().toLowerCase());modal(`<h3>Conteo físico de inventario</h3><div class="formgrid"><div class="field"><label>Producto</label><input id="countProduct" list="countProducts" value="${esc(p?.product||prefill||'')}"><datalist id="countProducts">${inventoryMasterRows().map(x=>`<option value="${esc(x.product)}">`).join('')}</datalist></div><div class="field"><label>Existencia del sistema</label><input id="systemQty" type="number" value="${Number(p?.qty||0)}" readonly></div><div class="field"><label>Cantidad física</label><input id="physicalQty" type="number" step=".001" value="${Number(p?.qty||0)}"></div><div class="field"><label>Unidad</label><input id="countUnit" value="${esc(p?.unit||'unidad')}"></div><div class="field"><label>Costo unitario</label><input id="countCost" type="number" step=".000001" value="${Number(p?.unitCost||0)}"></div><div class="field"><label>Mínimo</label><input id="countMin" type="number" step=".001" value="${Number(p?.minQty||0)}"></div><div class="field full"><div class="resultbox">Diferencia: <b id="countDiff">0</b> · Impacto: <b id="countDiffCost">$0.00</b></div></div></div><div class="card" id="scanBox" hidden><video id="barcodeVideo" autoplay playsinline style="width:100%"></video><input id="scanBarcode" placeholder="Código leído"></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn" data-action="start-scanner">📷 Escanear código</button><button class="btn primary" data-action="save-physical-count">Guardar conteo</button></div>`);['physicalQty','countCost'].forEach(id=>document.getElementById(id)?.addEventListener('input',calcCount));calcCount();} 
function calcCount(){const s=Number(document.getElementById('systemQty')?.value||0),p=Number(document.getElementById('physicalQty')?.value||0),c=Number(document.getElementById('countCost')?.value||0);const d=p-s;const e=document.getElementById('countDiff');const ec=document.getElementById('countDiffCost');if(e)e.textContent=Number.isFinite(d)?`${d>0?'+':''}${d.toLocaleString(undefined,{maximumFractionDigits:3})}`:'—';if(ec)ec.textContent=money(d*c)}
function savePhysicalCount(){const product=document.getElementById('countProduct')?.value.trim(),physical=Number(document.getElementById('physicalQty')?.value);if(!product||!Number.isFinite(physical)||physical<0)return toast('Indica producto y cantidad física');const unit=document.getElementById('countUnit').value.trim()||'u',cost=Number(document.getElementById('countCost').value||0),min=Number(document.getElementById('countMin').value||0);const linked=[...(master.products||[]),...(state.products||[])].find(x=>String(x.name||'').trim().toLowerCase()===product.toLowerCase());let inv=state.inventory.find(x=>(linked?.id&&String(x.productId)===String(linked.id)||String(x.product||'').toLowerCase()===product.toLowerCase())&&String(x.unit||'')===unit);if(!inv){inv={id:'INV-'+Date.now(),productId:linked?.id||'',product,unit,qty:0,unitCost:cost,minQty:min};state.inventory.push(inv)}else if(linked?.id&&!inv.productId)inv.productId=linked.id;const before=Number(inv.qty||0),diff=physical-before;inv.qty=physical;inv.unitCost=cost||Number(inv.unitCost||0);inv.minQty=min;const barcode=document.getElementById('scanBarcode').value.trim()||findBarcode(product);state.physicalCounts.push({id:'CNT-'+Date.now(),date:now(),product,barcode,unit,beforeQty:before,physicalQty:physical,difference:diff,differenceCost:diff*Number(inv.unitCost||0),minQty:min});if(barcode){const p=[...(master.products||[]),...(state.products||[])].find(x=>String(x.name||'').toLowerCase()===product.toLowerCase());if(p&&!p.barcode)p.barcode=barcode;inv.barcode=barcode;state.barcodeLog.push({id:'BAR-'+Date.now(),date:now(),barcode,product,source:'physical-count'})}state.movements.push({id:'MOV-'+Date.now(),date:now(),type:diff===0?'CONTEO SIN DIFERENCIA':(diff>0?'AJUSTE FÍSICO +':'AJUSTE FÍSICO -'),product,qty:diff,unit,ref:'CONTEO '+state.physicalCounts.at(-1).id});save();stopScanner();close();render();toast(diff===0?'Conteo guardado sin diferencia':`Conteo guardado: diferencia ${diff>0?'+':''}${diff}`)}
function startScanner(){const box=document.getElementById('scanBox'),video=document.getElementById('barcodeVideo');if(!box||!video)return;box.hidden=false;if(!('BarcodeDetector' in window)){toast('Este navegador no tiene lector automático. Puedes escribir el código manualmente.');return}navigator.mediaDevices?.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false}).then(stream=>{window._lrxScannerStream=stream;video.srcObject=stream;return video.play()}).then(()=>scanFrame()).catch(()=>toast('No se pudo acceder a la cámara'))}
async function scanFrame(){const video=document.getElementById('barcodeVideo');if(!video||!window._lrxScannerStream)return;try{const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e','code_128','code_39']});const codes=await detector.detect(video);if(codes?.length){const code=codes[0].rawValue;document.getElementById('scanBarcode').value=code;lookupBarcode(code);stopScanner();return}}catch(e){}requestAnimationFrame(scanFrame)}
function lookupBarcode(code){const c=String(code||'').trim();if(!c)return;const all=[...(master.products||[]),...(state.products||[])];const p=all.find(x=>String(x.barcode||'').trim()===c);if(p){const i=(state.inventory||[]).find(x=>String(x.product||'').toLowerCase()===String(p.name||'').toLowerCase());document.getElementById('countProduct').value=p.name;document.getElementById('systemQty').value=i?Number(i.qty||0):0;if(i){document.getElementById('countUnit').value=i.unit||'lb';document.getElementById('countCost').value=Number(i.unitCost||0);document.getElementById('countMin').value=Number(i.minQty||0)}calcCount();toast('Producto encontrado')}else toast('Código no registrado. Regístralo en Productos para asociarlo.');}
function stopScanner(){const s=window._lrxScannerStream;if(s){s.getTracks().forEach(t=>t.stop());window._lrxScannerStream=null}const v=document.getElementById('barcodeVideo');if(v)v.srcObject=null;const b=document.getElementById('scanBox');if(b)b.hidden=true}
function movements(){return head('Movimientos','Historial de entradas y salidas de inventario.',`<button class="btn" data-action="generic-export" data-key="movements">Exportar CSV</button>`)+`<div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Producto</th><th>Cantidad</th><th>Referencia</th></tr></thead><tbody>${state.movements.slice().reverse().map(x=>`<tr><td>${fmt(x.date,true)}</td><td>${esc(x.type)}</td><td>${esc(x.product)}</td><td>${esc(x.qty)} ${esc(x.unit)}</td><td>${esc(x.ref||'—')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Sin movimientos.</td></tr>'}</tbody></table></div>`}
