 const p=inventoryMasterRows().find(x=>String(x.productId||x.id)===String(prefill)||String(x.product||'').trim().toLowerCase()===String(prefill||'').trim().toLowerCase());
 modal(`<h3>Ajuste de inventario</h3><div class="formgrid"><div class="field"><label>Producto</label><input id="ip" list="invProducts" value="${esc(p?.product||prefill||'')}"><datalist id="invProducts">${inventoryMasterRows().map(x=>`<option value="${esc(x.product)}">`).join('')}</datalist></div><div class="field"><label>Nueva existencia</label><input id="iq" type="number" step=".001" value="${Number(p?.qty||0)}"></div><div class="field"><label>Unidad</label><input id="iu" value="${esc(p?.unit||'unidad')}"></div><div class="field"><label>Costo unitario</label><input id="ic" type="number" step=".000001" value="${Number(p?.unitCost||0)}"></div><div class="field"><label>Mínimo</label><input id="im" type="number" step=".001" value="${Number(p?.minQty||0)}"></div></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="save-adjust">Guardar ajuste</button></div>`);
