function formatModal(){modal(`<h3>Agregar formato</h3><div class="formgrid"><div class="field"><label>Nombre</label><input id="fn" placeholder="Ej. 2 × 1.5 in"></div><div class="field"><label>Ancho (in)</label><input id="fw" type="number" step=".01"></div><div class="field"><label>Alto (in)</label><input id="fh" type="number" step=".01"></div></div><div class="actions" style="margin-top:12px"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="save-format">Guardar</button></div>`);document.querySelector('[data-action="save-format"]').onclick=()=>{const w=+document.getElementById('fw').value,h=+document.getElementById('fh').value;if(!w||!h)return;state.settings.labelFormats.push({name:document.getElementById('fn').value||`${w} × ${h} in`,w,h});save();close();render()}}
function convert(){const q=+document.getElementById('cvq').value,a=document.getElementById('cva').value,b=document.getElementById('cvb').value,m={g:1,oz:28.349523125,lb:453.59237,kg:1000},v={mL:1,'fl oz':29.5735295625,pt:473.176473,qt:946.352946,gal:3785.411784,L:1000},c={unidad:1,docena:12};let r=null;if(m[a]&&m[b])r=q*m[a]/m[b];else if(v[a]&&v[b])r=q*v[a]/v[b];else if(c[a]&&c[b])r=q*c[a]/c[b];document.getElementById('cvres').textContent=r==null?'Conversión no permitida sin factor de densidad.':`${q} ${a} = ${r.toLocaleString(undefined,{maximumFractionDigits:6})} ${b}`}
function calc(){const c=+document.getElementById('cc').value||0,p=+document.getElementById('cp').value||0,cm=(+document.getElementById('cm').value||0)/100,cd=(+document.getElementById('cd').value||0)/100,n=p*(1-cd)*(1-cm),u=n-c,mar=n?u/n*100:0,fc=n?c/n*100:0;document.getElementById('cres').innerHTML=`<div class="grid"><div class="card"><small>Venta neta</small><strong>${money(n)}</strong></div><div class="card"><small>Utilidad</small><strong>${money(u)}</strong></div><div class="card"><small>Margen</small><strong>${mar.toFixed(2)}%</strong></div><div class="card"><small>Food Cost</small><strong>${fc.toFixed(2)}%</strong></div></div>`}
function integrationAudit(){
 const issues=[];
 const recipeNames=new Set(allRecipes().map(r=>String(r.name||'').trim().toLowerCase()).filter(Boolean));
 (state.sales||[]).forEach(s=>{if(s.inventoryDeducted&&!recipeNames.has(String(s.product||'').trim().toLowerCase()))issues.push(`Venta ${s.id}: marcada con inventario descontado pero sin receta vinculada`)});
 (state.production||[]).forEach(p=>{if(p.inventoryProduced&&!p.inventoryOutput)issues.push(`Producción ${p.id}: marcada como producto terminado sin movimiento de entrada`);if(p.inventoryConsumed&&!p.inventoryConsumption)issues.push(`Producción ${p.id}: marcada como consumo sin detalle de ingredientes`)});
 (state.purchases||[]).forEach(p=>{if(p.inventoryApplied&&!['RECIBIDA','PARCIAL'].includes(String(p.status||'')))issues.push(`Compra ${p.id}: inventario aplicado con estado ${p.status}`)});
 return {ok:issues.length===0,issues,counts:{sales:(state.sales||[]).length,production:(state.production||[]).length,purchases:(state.purchases||[]).length,movements:(state.movements||[]).length,inventory:(state.inventory||[]).length}};
}

function deepSystemAudit(){
 const issues=[],warnings=[];
 const productMap=new Map((master.products||[]).map(x=>[String(x.id),x]));
 const recipeList=allRecipes(); const recipeMap=new Map(recipeList.map(x=>[String(x.id),x]));
 const duplicateIds=(rows,label)=>{const seen=new Set();rows.forEach(x=>{const id=String(x?.id||'').trim();if(!id)return;if(seen.has(id))issues.push(`${label}: ID duplicado ${id}`);else seen.add(id)})};
 duplicateIds(master.products||[],'Productos maestros'); duplicateIds(recipeList,'Recetas/pre-elaborados'); duplicateIds(master.suppliers||[],'Proveedores maestros');
 const productNames=new Set((master.products||[]).map(x=>String(x.name||'').trim().toLowerCase()).filter(Boolean));
 const recipeNames=new Set(recipeList.map(x=>String(x.name||'').trim().toLowerCase()).filter(Boolean));
 const checks={};
 checks.masterProducts=(master.products||[]).length===381;
 checks.masterSuppliers=(master.suppliers||[]).length===30;
 checks.finalRecipes=(master.recipes||[]).filter(x=>x.type==='final').length===119;
 checks.preps=(master.recipes||[]).filter(x=>x.type==='pre').length===Number(master.meta?.prepCount||49);
 if(!checks.masterProducts)warnings.push(`Maestro SUP contiene ${(master.products||[]).length} productos; esperado 381.`);
 if(!checks.masterSuppliers)warnings.push(`Maestro de proveedores contiene ${(master.suppliers||[]).length}; esperado 30.`);
 if(!checks.finalRecipes)warnings.push(`Maestro contiene ${(master.recipes||[]).filter(x=>x.type==='final').length} recetas finales; esperado 119.`);
 if(!checks.preps)warnings.push(`Maestro contiene ${(master.recipes||[]).filter(x=>x.type==='pre').length} pre-elaborados; esperado ${Number(master.meta?.prepCount||49)}.`);
 recipeList.forEach(r=>{
   (r.items||[]).forEach(i=>{
     if(i.productId && !productMap.has(String(i.productId)) && !i.prepId) issues.push(`Receta ${r.name}: productId inexistente ${i.productId}`);
     if(!i.productId && !i.prepId && !productNames.has(String(i.product||i.ingredient||'').trim().toLowerCase())) warnings.push(`Receta ${r.name}: componente sin vínculo maestro: ${i.product||i.ingredient||'—'}`);
   });
 });
 (state.sales||[]).forEach(s=>{if(s.inventoryDeducted&&!s.inventoryImpact?.length)issues.push(`Venta ${s.id}: inventario marcado como descontado sin impacto registrado`);if(s.product&&!recipeNames.has(String(s.product).trim().toLowerCase())&&s.inventoryDeducted)issues.push(`Venta ${s.id}: producto sin receta maestra vinculada`) });
 (state.production||[]).forEach(p=>{if(p.inventoryProduced&&!p.inventoryOutput)issues.push(`Producción ${p.id}: sin movimiento de salida registrado`);if(p.inventoryConsumed&&!p.inventoryConsumption)issues.push(`Producción ${p.id}: sin detalle de consumo registrado`) });
 (state.purchases||[]).forEach(x=>{if(x.inventoryApplied&&String(x.status).toUpperCase()!=='RECIBIDA')issues.push(`Compra ${x.id}: inventario aplicado con estado ${x.status}`)});
 (state.inventory||[]).forEach(x=>{if(x.productId && !productMap.has(String(x.productId)) && !String(x.productId).startsWith('P-'))warnings.push(`Inventario ${x.product}: productId no está en el maestro`)});
 const invKeys=new Map();(state.inventory||[]).forEach(x=>{const k=`${String(x.productId||x.product||'').toLowerCase()}|${String(x.unit||'').toLowerCase()}`;if(invKeys.has(k))warnings.push(`Inventario duplicado: ${x.product} (${x.unit})`);else invKeys.set(k,x.id)});
 const required=['products','ingredients','suppliers','purchases','inventory','movements','waste','sales','production','recipes','preps','barRecipes','barPreps','dreRecords','budgets','employees','employeeConsumptions','resources','events','checklistTasks','managerLogs','incidents','maintenance','partners','companyDocuments','financialDocuments','permits','refrigerationMoves','documents'];
 required.forEach(k=>{if(!Array.isArray(state[k]))issues.push(`Estructura inválida: ${k} no es arreglo`) });
 const rq=master.meta?.reconciliationQueue||{};
 if(Number(master.meta?.reconciliationAmbiguous||0)) warnings.push(`SUP: ${Number(master.meta.reconciliationAmbiguous)} componentes requieren selección entre productos maestros ambiguos.`);
 if(Number(master.meta?.reconciliationMissing||0)) warnings.push(`SUP: ${Number(master.meta.reconciliationMissing)} componentes no tienen producto maestro equivalente; no se asignó un vínculo inventado.`);
 return {ok:issues.length===0,issues,warnings,checks,reconciliation:{resolvedSafe:Number(master.meta?.reconciliationResolvedSafe||0),ambiguous:Number(master.meta?.reconciliationAmbiguous||0),missing:Number(master.meta?.reconciliationMissing||0),queue:rq},counts:Object.fromEntries(required.map(k=>[k,Array.isArray(state[k])?state[k].length:0]))};
}
function masterIntegritySummary(){const dup=(arr,key='id')=>{const m=new Map();(arr||[]).forEach(x=>{const v=String(x?.[key]||'').trim();if(v)m.set(v,(m.get(v)||0)+1)});return [...m.entries()].filter(([,n])=>n>1).map(([id,n])=>({id,count:n}))};return {products:dup(master.products),recipes:dup(master.recipes),suppliers:dup(master.suppliers),stateProducts:dup(state.products),stateRecipes:dup(state.recipes),statePreps:dup(state.preps)}}

function backupData(){const blob=new Blob([JSON.stringify({app:'LRX',version:APP_VERSION,exportedAt:now(),state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`LRX-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);audit('BACKUP','Respaldo manual exportado');toast('Respaldo descargado')}
function restoreData(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const obj=JSON.parse(r.result);const incoming=obj.state||obj;if(!incoming||typeof incoming!=='object')throw new Error('Formato inválido');for(const k of Object.keys(state)){if(Array.isArray(incoming[k]))state[k]=incoming[k]}if(incoming.settings&&typeof incoming.settings==='object')state.settings={...state.settings,...incoming.settings};state.currentUserId=incoming.currentUserId||state.currentUserId;save();render();toast('Respaldo restaurado')}catch(e){toast('Respaldo inválido')}};r.readAsText(file)}

function hydrateMasterData(){
  // Central master hydration: master data is the source of truth for catalogs.
  // User records are preserved and never overwritten.
  const products=Array.isArray(master.products)?master.products:[];
  const suppliers=Array.isArray(master.suppliers)?master.suppliers:[];
  if(!Array.isArray(state.ingredients)||!state.ingredients.length){
    state.ingredients=products.map(p=>({id:'ING-'+p.id,productId:p.id,name:p.name,category:p.category||'',unit:p.unit||'unidad',cost:Number(p.finalCost||p.cost||p.price||0),source:'MASTER SUP'}));
  }
  if(!Array.isArray(state.categories)||!state.categories.length){
    state.categories=[...new Set(products.map(p=>String(p.category||'').trim()).filter(Boolean))].map((name,i)=>({id:'CAT-'+String(i+1).padStart(3,'0'),name,source:'MASTER SUP'}));
  }
  if(!Array.isArray(state.suppliers)||!state.suppliers.length){
    state.suppliers=suppliers.map((x,i)=>typeof x==='string'?{id:'SUPP-'+String(i+1).padStart(3,'0'),name:x,source:'MASTER SUP'}:{...x,id:x.id||'SUPP-'+String(i+1).padStart(3,'0'),source:'MASTER SUP'});
  }
  // Inventory is virtualized from the product master when no local inventory row exists.
  // This makes every product visible to inventory without creating fake movements.
  if(!Array.isArray(state.inventory)) state.inventory=[];
}


